 const syncImportButtons=()=>{const locked=$('import').disabled||!!tools.isBusy?.(),count=checked.size,current=engineItems.find(e=>e.token===$('engine-library').value);const pageTargets=selectableOf(currentPageItems),filteredTargets=selectableOf(currentFilteredItems),pageAllChecked=pageTargets.length>0&&pageTargets.every(item=>checked.has(item.id));$('engine-render-mode').parentElement.hidden=!(['scene','web'].includes(current?.type)||engineItems.some(e=>checked.has(e.id)&&['scene','web'].includes(e.type)));$('cwb-batch-status').textContent='已勾选 '+count+' 项'+(count>=100?'（已达单次 100 项上限）':'');$('cwb-batch-select-page').textContent=pageAllChecked?'取消本页':'全选本页';$('cwb-batch-select-page').disabled=locked||!pageTargets.length;$('cwb-batch-select-filtered').textContent=currentViewHidden?'全选筛选（最多100）':'全选筛选未导入'+(filteredTargets.length?'（'+Math.min(filteredTargets.length,100)+'）':'');$('cwb-batch-select-filtered').disabled=locked||!filteredTargets.length;$('cwb-batch-import').disabled=!count||locked;$('cwb-batch-clear').disabled=!count||locked;$('cwb-batch-import').textContent=count?([...checked].every(id=>failedIds.has(id))?'仅重试失败的 '+count+' 项':'批量保存 '+count+' 项'):'批量保存勾选项';$('engine-import').textContent='导入当前项并应用';$('engine-save').textContent='仅保存当前项';};
