 const inspect=(item,inspection,loading)=>{selectedToken=item?.token;$('cwb-selected-name').textContent=item?.title||'请选择壁纸';$('cwb-selected-image').hidden=true;if(!item)return;const token=item.token;loadPreview(item).then(result=>{if(selectedToken===token&&result.preview){$('cwb-selected-image').src=result.preview;$('cwb-selected-image').hidden=false;}}).catch(()=>{});const badge=$('cwb-badge-'+item.token);if(badge)badge.textContent=loading?'检测中…':inspection?.label||'待检测';};

 const segmentedSyncs=[];
 const attachSegmented=(selectEl,shortMap)=>{
  if(!selectEl||selectEl.dataset.cwbSegmented)return;
  selectEl.dataset.cwbSegmented='1';selectEl.hidden=true;
  const seg=document.createElement('div');seg.className='cwb-seg';seg.setAttribute('role','group');
  const sync=()=>{
   for(const btn of seg.children){
    const active=btn.dataset.value===selectEl.value;
    btn.classList.toggle('active',active);
    btn.setAttribute('aria-pressed',String(active));
    btn.disabled=!!selectEl.disabled||!!tools.isBusy?.();
   }
  };
  for(const opt of selectEl.options){
   const btn=document.createElement('button');btn.type='button';btn.className='cwb-seg-btn';btn.dataset.value=opt.value;btn.dataset.cwbControl='';btn.id=selectEl.id+'-seg-'+opt.value;
   btn.textContent=shortMap?.[opt.value]||opt.textContent;
   btn.onclick=()=>{if(selectEl.disabled||tools.isBusy?.())return;if(selectEl.value!==opt.value){selectEl.value=opt.value;selectEl.dispatchEvent(new Event('change'));}sync();};
   seg.append(btn);
  }
  selectEl.after(seg);selectEl.addEventListener('change',sync);segmentedSyncs.push(sync);sync();
 };

 const author=document.createElement('details');author.className='cwb-feature';author.id='cwb-author-properties';
