 const authorStatus=document.createElement('p');authorStatus.id='cwb-author-status';authorStatus.setAttribute('role','status');const authorFields=document.createElement('div');authorFields.id='cwb-author-fields';const authorReset=control('button','cwb-author-reset');authorReset.type='button';authorReset.className='cwb-soft-btn';authorReset.textContent='恢复作者默认值';author.append(authorStatus,authorFields,authorReset);
