 const definitions=[['theme','透明界面配色',['auto','light','dark'],'自动根据当前壁纸明暗切换前景色'],['glassBlur','玻璃模糊强度',0,24,1],['glassOpacity','玻璃不透明度',.2,1,.05],['brightness','壁纸亮度',.25,1.5,.05],['wallpaperBlur','壁纸模糊',0,20,1],['fontFamily','界面字体',['inherit','system-ui','Microsoft YaHei','KaiTi','SimSun']],['codeFontFamily','代码字体',['inherit','Consolas','Cascadia Code','monospace']],['fontSize','界面字号',12,22,1],['parallax','背景视差位移',0,30,1],['speed','视频播放速度',.25,2,.25],['transitionMs','切换淡入时长',0,1000,50],['flip','水平翻转壁纸','boolean'],['volume','WebGL 场景音量',0,1,.05],['fxEnabled','启用光标交互特效','boolean','关闭后自动收起细项参数，保持界面清爽'],['fxClick','显示点击效果','boolean'],['fxTrail','显示光标拖尾','boolean'],['fxClickStyle','点击样式',['ripple','spark','both']],['fxTrailStyle','拖尾样式',['comet','dust']],['fxColorMode','特效配色',['accent','rainbow','custom']],['fxColor','自定义特效颜色','color'],['fxClickSize','点击半径',40,400,10],['fxClickGlow','点击光晕',0,100,5],['fxTrailLength','拖尾时长',80,2000,20],['fxTrailWidth','拖尾粗细',1,12,1],['fxTrailGlow','拖尾光晕',0,100,5],['fxOpacity','特效不透明度',10,100,5],['fxBlend','特效混合',['auto','screen','normal','lighten']]];
 const labels={auto:'跟随壁纸',light:'浅色',dark:'深色',inherit:'跟随原生','system-ui':'系统界面字体','Microsoft YaHei':'微软雅黑',KaiTi:'楷体',SimSun:'宋体',ripple:'涟漪',spark:'星火',both:'两者',comet:'彗星',dust:'星尘',accent:'跟随壁纸',rainbow:'彩虹',custom:'自定义',screen:'滤色',normal:'普通',lighten:'变亮'};
 const formatVisualValue=(key,value)=>{
  const n=Number(value);if(!Number.isFinite(n))return '';
  if(['glassBlur','wallpaperBlur','fontSize','parallax','fxClickSize','fxTrailWidth'].includes(key))return Math.round(n)+'px';
  if(['glassOpacity','brightness','volume'].includes(key))return Math.round(n*100)+'%';
  if(['fxClickGlow','fxTrailGlow','fxOpacity'].includes(key))return Math.round(n)+'%';
  if(key==='speed')return n.toFixed(2).replace(/\.00$/,'')+'×';
  if(['transitionMs','fxTrailLength'].includes(key))return Math.round(n)+'ms';
  return String(n);
 };
 const syncSliderVisual=(input,key)=>{const min=Number(input.min||0),max=Number(input.max||100),val=Number(input.value||0);input.style.setProperty('--cwb-range-pct',(max>min?Math.max(0,Math.min(100,((val-min)/(max-min))*100)):0)+'%');const out=input.parentElement?.querySelector('output');if(out)out.textContent=formatVisualValue(key,input.value);};
 const visualSegMaps={theme:{auto:'跟随壁纸',light:'浅色',dark:'深色'},fxClickStyle:{ripple:'涟漪',spark:'星火',both:'两者'},fxTrailStyle:{comet:'彗星',dust:'星尘'},fxColorMode:{accent:'跟随壁纸',rainbow:'彩虹',custom:'自定义'},fxBlend:{auto:'自动',screen:'滤色',normal:'普通',lighten:'变亮'}};
 const makeGroup=(parent,title)=>{const cap=document.createElement('p');cap.className='cwb-group-label';cap.textContent=title;const box=document.createElement('div');box.className='cwb-inset-group';parent.append(cap,box);return box;};
 const gGlass=makeGroup(fields,'界面主题与玻璃质感'),gMedia=makeGroup(fields,'字体与动态细节'),gFx=makeGroup(fxSection,'光标点击与拖尾特效');
