 const glassKeys=new Set(['theme','glassBlur','glassOpacity','brightness','wallpaperBlur']);
 for(const [key,title,type,maxOrDesc,step]of definitions){
  const isRange=!Array.isArray(type)&&type!=='boolean'&&type!=='color';
  const desc=!isRange&&typeof maxOrDesc==='string'?maxOrDesc:'';
  const label=document.createElement('label');label.className='cwb-setting-row';
  const meta=document.createElement('span');meta.className='cwb-row-meta';
  const nameSpan=document.createElement('span');nameSpan.className='cwb-row-title';nameSpan.textContent=title;meta.append(nameSpan);
  if(desc){const d=document.createElement('span');d.className='cwb-row-desc';d.textContent=desc;meta.append(d);}
  label.append(meta);
  const ctrlWrap=document.createElement('span');ctrlWrap.className='cwb-row-ctrl';
  const input=control(Array.isArray(type)?'select':'input','visual-'+key);
  if(Array.isArray(type)){for(const value of type){const option=document.createElement('option');option.value=value;option.textContent=key==='fxBlend'&&value==='auto'?'自动（随壁纸明暗）':labels[value]||value;input.append(option);}ctrlWrap.append(input);}
  else if(type==='boolean'){label.classList.add('cwb-switch-field');input.type='checkbox';ctrlWrap.append(input);}
  else if(type==='color'){input.type='color';ctrlWrap.append(input);}
  else{label.classList.add('cwb-range-field');ctrlWrap.classList.add('cwb-slider-wrap');input.type='range';input.min=type;input.max=maxOrDesc;input.step=step;input.oninput=()=>syncSliderVisual(input,key);const out=document.createElement('output');out.id='visual-'+key+'-val';ctrlWrap.append(input,out);}
  label.append(ctrlWrap);
  if(glassKeys.has(key))gGlass.append(label);
  else if(key==='fxEnabled')gFx.append(label);
  else if(fxChildKeys.has(key))fxChildren.append(label);
  else gMedia.append(label);
  if(visualSegMaps[key])attachSegmented(input,visualSegMaps[key]);
  input.onchange=()=>busy(()=>send({action:'visual',values:{[key]:type==='boolean'?input.checked:Array.isArray(type)||type==='color'?input.value:Number(input.value)}}));
 }
 const fxHint=document.createElement('p');fxHint.id='cwb-fx-hint';fxHint.className='cwb-inline-note';fxHint.textContent='这组特效叠加在壁纸上。回到 Codex 主窗口，移动光标或点击空白处即可预览。';
