 const syncRotationSelection=()=>{const opts=[...$('cwb-rotation-items').options],selected=opts.filter(o=>o.selected&&!o.disabled).length,pending=opts.filter(o=>o.disabled).length,pendingList=pendingRealtimeEntries(),locked=!!tools.isBusy?.();$('cwb-rotation-count').textContent=(selected?`已选 ${selected} 项（点击“保存轮播设置”生效）`:'未勾选，默认轮播全部已确认项目')+(pending?` · 另有 ${pending} 项待首次确认，确认前不参与轮播`:'');$('cwb-rotation-clear').disabled=locked||!selected;$('cwb-rotation-approve-all').hidden=!pendingList.length;$('cwb-rotation-approve-all').disabled=locked||!pendingList.length;$('cwb-rotation-approve-all').textContent='批量确认（'+pendingList.length+' 项）';};
 $('cwb-rotation-approve-all').onclick=()=>busy(async()=>{const pendingList=pendingRealtimeEntries();if(!pendingList.length)return {config,message:'没有待确认的实时壁纸。'};const webgl=pendingList.filter(e=>e.mode==='webwallgl').length,web=pendingList.filter(e=>e.engine==='chromium-web').length,native=pendingList.length-webgl-web,parts=[];if(webgl)parts.push('GPU 直绘（WebGL）'+webgl+' 项');if(native)parts.push('原版兼容 '+native+' 项');if(web)parts.push('网页浏览器 '+web+' 项');const names=pendingList.slice(0,12).map(e=>e.name).join('、')+(pendingList.length>12?' 等共 '+pendingList.length+' 项':'');const text='将为以下 '+pendingList.length+' 项实时壁纸授予运行确认（'+parts.join('，')+'）：\n'+names+'\n\n说明：这些项目会在切换或轮播到它们时执行作者脚本或启动对应渲染；本次授权不立即切换当前背景，确认后即可参与轮播，个别失败项轮播时会自动跳过。';if(!await tools.askChoice('批量确认实时壁纸（'+pendingList.length+' 项）',text,'确认授权'))return {config,cancelled:true,message:'已取消批量确认。'};const allIds=pendingList.map(e=>e.id);let lastConfig=config,authorized=0,skipped=0;for(let i=0;i<allIds.length;i+=500){const r=await send({action:'realtime-authorize-batch',ids:allIds.slice(i,i+500),confirmed:true});if(r.config)lastConfig=r.config;authorized+=r.authorized?.length||0;skipped+=r.skipped?.length||0;}return {config:lastConfig,message:'已确认 '+authorized+' 项实时壁纸的运行授权，可直接参与轮播；'+(skipped?'跳过 '+skipped+' 项不可用项目；':'')+'当前背景保持不变。'};},'批量确认失败');
