 let latestMedia={capabilities:{}};const renderMedia=payload=>{latestMedia=payload;if(!host.__cwbMediaPanelVisible?.())return;const enabled=config.systemMedia?.enabled;const audio=config.systemMedia?.audio;const states=(payload.sources||[]).map(source=>source.name+': '+source.state).join('；');$('cwb-media-status').textContent=!enabled&&!audio?'歌曲信息和音频响应均已关闭':payload.error?payload.error:payload.hasMedia?(payload.state===1?'播放中 · ':payload.state===2?'已暂停 · ':'')+payload.title+(payload.artist?' · '+payload.artist:'')+' · '+(payload.sourceName||'未知'):(audio?'音频响应已开启。':'未发现正在播放的系统媒体。')+states;const stageText={disabled:'音频响应已关闭','no-scene':'当前壁纸不是 WebGL 场景',unsupported:'当前场景不使用音频频谱','scene-paused':'场景已暂停',starting:'正在启动系统音频采集','capture-error':'系统音频采集启动失败','capture-stale':'系统音频采集缺帧或输出设备不可用','awaiting-capture':'正在等待系统音频频谱','awaiting-renderer':'采集已有数据，当前页面尚未收到频谱',receiving:'正在接收频谱'};if(audio&&stageText[payload.audioStage])$('cwb-media-status').textContent+=' · '+stageText[payload.audioStage];if(audio&&payload.audioReason)$('cwb-media-status').textContent+='；'+payload.audioReason;const requested=config.systemMedia?.audioFps;if(audio&&payload.targetRate){$('cwb-media-status').textContent+=' · 目标 '+payload.targetRate+'Hz';if(payload.receivedHz!=null)$('cwb-media-status').textContent+=' · 实收 '+payload.receivedHz+'Hz';}$('cwb-media-playPause').textContent=payload.state===1?'暂停':'播放';for(const [command,capability]of [['previous','previous'],['playPause','toggle'],['next','next']]){const capable=command==='playPause'?((payload.state===1?payload.capabilities?.pause:payload.capabilities?.play)||payload.capabilities?.toggle):payload.capabilities?.[capability];$('cwb-media-'+command).disabled=!!tools.isBusy?.()||!enabled||!!payload.error||!capable;}};host.__cwbSystemMedia=renderMedia;
